/** Every Outbound type the backend registry can construct. */
export type OutboundTypeName = keyof typeof OUTBOUND_INVENTORY

/**
 * The field keys valid for one Outbound type. Curation is keyed by this, so naming
 * a field sing-box does not have — or one it dropped in an upgrade — is a
 * compile error rather than an input that never binds.
 */
export type OutboundFieldKey<T extends OutboundTypeName> = Extract<
  keyof (typeof OUTBOUND_INVENTORY)[T],
  string
>

export const OUTBOUND_TYPE_NAMES = Object.keys(OUTBOUND_INVENTORY) as OutboundTypeName[]

